CREATE OR REPLACE FUNCTION public.documento_central_evento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
    VALUES ('documento_recebido', 'documento_central', NEW.id,
      jsonb_build_object('categoria', NEW.categoria, 'titulo', NEW.titulo,
        'reserva_id', NEW.reserva_id, 'lead_id', NEW.lead_id, 'expedicao_id', NEW.expedicao_id));
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'enviado' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('documento_enviado', 'documento_central', NEW.id,
        jsonb_build_object('categoria', NEW.categoria, 'titulo', NEW.titulo));
    ELSIF NEW.status = 'aprovado' THEN
      NEW.aprovado_em := COALESCE(NEW.aprovado_em, now());
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('documento_aprovado', 'documento_central', NEW.id,
        jsonb_build_object('categoria', NEW.categoria, 'titulo', NEW.titulo));
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.gerar_resumo_ia_lead()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    resumo TEXT;
    p_info TEXT := '';
    r RECORD;
    res_record RECORD;

    -- Campos de Memória
    v_perfil TEXT;
    v_objetivos TEXT;
    v_interesses TEXT;
    v_restricoes TEXT;
    v_orcamento TEXT;
    v_idade TEXT := 'Não informada';
    v_tipo_grupo TEXT := 'individual';
BEGIN
    -- Busca dados da reserva associada se existirem
    SELECT * INTO res_record FROM public.reservas WHERE lead_id = NEW.id OR id = NEW.id LIMIT 1;

    -- 1. INFERÊNCIA DE PERFIL
    IF NEW.data_nascimento IS NOT NULL THEN
        v_idade := date_part('year', age(NEW.data_nascimento)) || ' anos';
    END IF;

    IF NEW.quantidade_pessoas > 2 THEN
        v_tipo_grupo := 'família/amigos';
    ELSIF NEW.quantidade_pessoas = 2 THEN
        v_tipo_grupo := 'casal/amigos';
    ELSE
        v_tipo_grupo := 'individual';
    END IF;

    v_perfil := format('Origem: %s/%s. Idade: %s. Grupo: %s (%s pessoas).', 
        COALESCE(NEW.cidade, 'Não informada'), 
        COALESCE(NEW.estado, '-'),
        v_idade,
        v_tipo_grupo,
        COALESCE(NEW.quantidade_pessoas, 1)
    );

    -- 2. INFERÊNCIA DE OBJETIVOS
    v_objetivos := 'Turismo de experiência e contato com a natureza.';
    IF NEW.observacoes ILIKE '%aventura%' OR NEW.expedicao_interesse ILIKE '%travessia%' THEN
        v_objetivos := 'Turismo de aventura, superação e desafios técnicos.';
    ELSIF NEW.observacoes ILIKE '%descansar%' OR NEW.observacoes ILIKE '%paz%' OR NEW.observacoes ILIKE '%tranquil%' THEN
        v_objetivos := 'Desconexão, relaxamento e busca por tranquilidade.';
    ELSIF NEW.expedicao_interesse ILIKE '%mulher%' THEN
        v_objetivos := 'Experiência exclusiva para o público feminino.';
    ELSIF NEW.observacoes ILIKE '%grupo%' OR NEW.observacoes ILIKE '%conhecer pessoas%' THEN
        v_objetivos := 'Integração em grupo e socialização.';
    END IF;

    -- 3. INFERÊNCIA DE INTERESSES
    v_interesses := format('Expedição: %s.', COALESCE(NEW.expedicao_interesse, 'Turismo equestre'));
    IF NEW.experiencia_equestre IS NOT NULL AND NEW.experiencia_equestre != '' THEN
        v_interesses := v_interesses || ' Nível de experiência: ' || NEW.experiencia_equestre || '.';
    END IF;

    IF NEW.expedicao_interesse ILIKE '%Canastra%' THEN
        v_interesses := v_interesses || ' Interesses específicos: Natureza, Cultura local, Gastronomia (Queijos).';
    ELSIF NEW.expedicao_interesse ILIKE '%Pantanal%' THEN
        v_interesses := v_interesses || ' Interesses específicos: Observação de fauna, Safari, Biodiversidade.';
    ELSIF NEW.expedicao_interesse ILIKE '%Marajó%' THEN
        v_interesses := v_interesses || ' Interesses específicos: Cultura paraense, Búfalos, Praias de rio.';
    END IF;

    -- 4. INFERÊNCIA DE RESTRIÇÕES
    v_restricoes := 'Nenhuma informada.';
    IF (NEW.restricoes_alimentares IS NOT NULL AND NEW.restricoes_alimentares != '') OR 
       (NEW.observacoes_medicas IS NOT NULL AND NEW.observacoes_medicas != '') THEN
        v_restricoes := '';
        IF NEW.restricoes_alimentares IS NOT NULL AND NEW.restricoes_alimentares != '' THEN
            v_restricoes := 'Alimentares: ' || NEW.restricoes_alimentares;
        END IF;
        IF NEW.observacoes_medicas IS NOT NULL AND NEW.observacoes_medicas != '' THEN
            IF v_restricoes != '' THEN v_restricoes := v_restricoes || '. '; END IF;
            v_restricoes := v_restricoes || 'Médicas/Físicas: ' || NEW.observacoes_medicas;
        END IF;
    END IF;

    -- Tenta consolidar restrições dos participantes da reserva
    IF res_record.id IS NOT NULL AND res_record.participantes IS NOT NULL THEN
        FOR r IN SELECT * FROM jsonb_to_recordset(res_record.participantes) AS x(nome TEXT, restricoes_alimentares TEXT, observacoes_medicas TEXT)
        LOOP
            IF (r.restricoes_alimentares IS NOT NULL AND r.restricoes_alimentares != '') OR 
               (r.observacoes_medicas IS NOT NULL AND r.observacoes_medicas != '') THEN
                IF v_restricoes = 'Nenhuma informada.' THEN v_restricoes := ''; END IF;
                v_restricoes := v_restricoes || format(E'\n- %s: %s %s', r.nome, COALESCE(r.restricoes_alimentares, ''), COALESCE(r.observacoes_medicas, ''));
            END IF;
        END LOOP;
    END IF;

    -- 5. INFERÊNCIA DE ORÇAMENTO
    v_orcamento := format('Valor total: R$ %s (%s participantes).', 
        TO_CHAR(COALESCE(res_record.valor_total, NEW.valor_estimado, 0), 'FM999G999G990D00'),
        COALESCE(NEW.quantidade_pessoas, 1)
    );
    IF NEW.forma_pagamento IS NOT NULL OR res_record.forma_pagamento IS NOT NULL THEN
        v_orcamento := v_orcamento || ' Forma preferencial: ' || COALESCE(res_record.forma_pagamento, NEW.forma_pagamento) || '.';
    END IF;

    -- UPSERT na lead_memoria
    INSERT INTO public.lead_memoria (lead_id, perfil, objetivos, interesses, restricoes, orcamento, ultima_atualizacao)
    VALUES (NEW.id, v_perfil, v_objetivos, v_interesses, v_restricoes, v_orcamento, now())
    ON CONFLICT (lead_id) DO UPDATE SET
        perfil = EXCLUDED.perfil,
        objetivos = EXCLUDED.objetivos,
        interesses = EXCLUDED.interesses,
        restricoes = EXCLUDED.restricoes,
        orcamento = EXCLUDED.orcamento,
        ultima_atualizacao = now();

    -- CONSTRUÇÃO DO RESUMO CONSOLIDADO (resumo_ia)
    resumo := format(
        '%s, %s, residente em %s/%s.
Interessado na expedição %s para um grupo de %s participantes.
Busca %s
Orçamento estimado: %s.',
        NEW.nome, v_idade, COALESCE(NEW.cidade, 'Não informada'), COALESCE(NEW.estado, '-'),
        COALESCE(NEW.expedicao_interesse, 'Não informada'), 
        COALESCE(NEW.quantidade_pessoas, 1),
        LOWER(v_objetivos),
        v_orcamento
    );

    IF v_restricoes != '' AND v_restricoes != 'Nenhuma informada.' THEN
        resumo := resumo || E'\n\nRestrições/Observações:\n' || v_restricoes;
    END IF;

    NEW.resumo_ia := resumo;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_internal_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  total int;
BEGIN
  SELECT COUNT(*) INTO total FROM public.user_roles;
  IF total = 0 THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, 'admin')
    ON CONFLICT (user_id, role) DO NOTHING;
  ELSE
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, 'operador')
    ON CONFLICT (user_id, role) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ia_abrir_handoff(p_motivo text, p_prioridade text DEFAULT 'media'::text, p_lead_id uuid DEFAULT NULL::uuid, p_reserva_id uuid DEFAULT NULL::uuid, p_contexto jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_msg text;
BEGIN
  IF NOT public._ia_pode_atuar() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  IF coalesce(trim(p_motivo),'') = '' THEN
    v_msg := 'Motivo obrigatório';
    PERFORM public._ia_log('ia_abrir_handoff', jsonb_build_object('motivo',p_motivo),
      '{}'::jsonb, false, v_msg, p_lead_id, p_reserva_id);
    RETURN jsonb_build_object('ok', false, 'motivo', v_msg);
  END IF;
  INSERT INTO public.ia_handoff_queue(motivo, prioridade, origem, lead_id, reserva_id, notas, status)
  VALUES (p_motivo, p_prioridade, 'ia', p_lead_id, p_reserva_id, p_contexto::text, 'pendente')
  RETURNING id INTO v_id;
  PERFORM public._ia_log('ia_abrir_handoff',
    jsonb_build_object('motivo', p_motivo, 'prioridade', p_prioridade, 'contexto', p_contexto),
    jsonb_build_object('handoff_id', v_id), true, NULL, p_lead_id, p_reserva_id);
  RETURN jsonb_build_object('ok', true, 'handoff_id', v_id);
END $function$

CREATE OR REPLACE FUNCTION public.ia_anexar_memoria(p_lead_id uuid, p_chave text, p_valor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ok boolean := false; v_msg text;
BEGIN
  IF NOT public._ia_pode_atuar() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  IF coalesce(trim(p_chave),'') = '' THEN
    v_msg := 'Chave vazia';
  ELSIF NOT EXISTS (SELECT 1 FROM public.leads WHERE id = p_lead_id) THEN
    v_msg := 'Lead não encontrado';
  ELSE
    INSERT INTO public.lead_memoria(lead_id, dados_extraidos, ultima_atualizacao)
    VALUES (p_lead_id, jsonb_build_object(p_chave, p_valor), now())
    ON CONFLICT (lead_id) DO UPDATE
      SET dados_extraidos = public.lead_memoria.dados_extraidos || jsonb_build_object(p_chave, p_valor),
          ultima_atualizacao = now();
    v_ok := true;
  END IF;
  PERFORM public._ia_log('ia_anexar_memoria',
    jsonb_build_object('chave', p_chave, 'valor', p_valor),
    jsonb_build_object('ok', v_ok), v_ok, v_msg, p_lead_id, NULL);
  RETURN jsonb_build_object('ok', v_ok, 'motivo', v_msg);
END $function$

CREATE OR REPLACE FUNCTION public.ia_atualizar_temperatura(p_lead_id uuid, p_temperatura text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ok boolean := false; v_msg text;
BEGIN
  IF NOT public._ia_pode_atuar() THEN
    RAISE EXCEPTION 'Sem permissão para atuar como IA';
  END IF;
  IF p_temperatura NOT IN ('frio','morno','quente') THEN
    v_msg := 'Temperatura inválida'; 
  ELSIF NOT EXISTS (SELECT 1 FROM public.leads WHERE id = p_lead_id) THEN
    v_msg := 'Lead não encontrado';
  ELSE
    UPDATE public.leads SET temperatura_lead = p_temperatura, updated_at = now() WHERE id = p_lead_id;
    v_ok := true;
  END IF;
  PERFORM public._ia_log('ia_atualizar_temperatura',
    jsonb_build_object('temperatura', p_temperatura, 'motivo', p_motivo),
    jsonb_build_object('ok', v_ok), v_ok, v_msg, p_lead_id, NULL);
  RETURN jsonb_build_object('ok', v_ok, 'motivo', v_msg);
END $function$

CREATE OR REPLACE FUNCTION public.ia_avancar_etapa(p_lead_id uuid, p_nova_etapa text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ok boolean := false; v_msg text; v_etapas_ia text[] :=
  ARRAY['novo','qualificado','proposta_enviada','reserva_pendente','participante_confirmado'];
BEGIN
  IF NOT public._ia_pode_atuar() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  IF NOT (p_nova_etapa = ANY (v_etapas_ia)) THEN
    v_msg := 'Etapa fora da whitelist da IA (terminais exigem humano)';
  ELSIF NOT EXISTS (SELECT 1 FROM public.leads WHERE id = p_lead_id) THEN
    v_msg := 'Lead não encontrado';
  ELSE
    UPDATE public.leads
       SET etapa_atendimento = p_nova_etapa, updated_at = now()
     WHERE id = p_lead_id;
    v_ok := true;
  END IF;
  PERFORM public._ia_log('ia_avancar_etapa',
    jsonb_build_object('nova_etapa', p_nova_etapa, 'motivo', p_motivo),
    jsonb_build_object('ok', v_ok), v_ok, v_msg, p_lead_id, NULL);
  RETURN jsonb_build_object('ok', v_ok, 'motivo', v_msg);
END $function$

CREATE OR REPLACE FUNCTION public.ia_concluir_tarefa(p_tarefa_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_origem text; v_ok boolean := false; v_msg text;
        v_lead uuid; v_reserva uuid;
BEGIN
  IF NOT public._ia_pode_atuar() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  SELECT origem, lead_id, reserva_id INTO v_origem, v_lead, v_reserva
  FROM public.tarefas WHERE id = p_tarefa_id;
  IF NOT FOUND THEN
    v_msg := 'Tarefa não encontrada';
  ELSIF v_origem <> 'ia' THEN
    v_msg := 'IA só pode concluir tarefas de origem ia';
  ELSE
    UPDATE public.tarefas
       SET status='concluida', concluida_em=now(), updated_at=now()
     WHERE id = p_tarefa_id;
    v_ok := true;
  END IF;
  PERFORM public._ia_log('ia_concluir_tarefa',
    jsonb_build_object('tarefa_id', p_tarefa_id),
    jsonb_build_object('ok', v_ok), v_ok, v_msg, v_lead, v_reserva);
  RETURN jsonb_build_object('ok', v_ok, 'motivo', v_msg);
END $function$

CREATE OR REPLACE FUNCTION public.ia_criar_tarefa(p_titulo text, p_descricao text DEFAULT NULL::text, p_prioridade text DEFAULT 'media'::text, p_lead_id uuid DEFAULT NULL::uuid, p_reserva_id uuid DEFAULT NULL::uuid, p_participante_id uuid DEFAULT NULL::uuid, p_prazo_horas integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_msg text;
BEGIN
  IF NOT public._ia_pode_atuar() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  IF coalesce(trim(p_titulo),'') = '' THEN
    v_msg := 'Título vazio';
    PERFORM public._ia_log('ia_criar_tarefa',
      jsonb_build_object('titulo', p_titulo), '{}'::jsonb, false, v_msg, p_lead_id, p_reserva_id);
    RETURN jsonb_build_object('ok', false, 'motivo', v_msg);
  END IF;
  v_id := public.criar_tarefa_idempotente(
    p_titulo, 'geral', 'ia', p_prioridade,
    p_lead_id, p_reserva_id, p_participante_id,
    make_interval(hours => GREATEST(1, p_prazo_horas))
  );
  IF p_descricao IS NOT NULL THEN
    UPDATE public.tarefas SET descricao = p_descricao WHERE id = v_id;
  END IF;
  PERFORM public._ia_log('ia_criar_tarefa',
    jsonb_build_object('titulo', p_titulo, 'prioridade', p_prioridade, 'prazo_horas', p_prazo_horas),
    jsonb_build_object('tarefa_id', v_id), true, NULL, p_lead_id, p_reserva_id);
  RETURN jsonb_build_object('ok', true, 'tarefa_id', v_id);
END $function$

CREATE OR REPLACE FUNCTION public.ia_registrar_interacao(p_lead_id uuid, p_reserva_id uuid DEFAULT NULL::uuid, p_canal text DEFAULT 'whatsapp'::text, p_direcao text DEFAULT 'out'::text, p_conteudo text DEFAULT NULL::text, p_resposta_final text DEFAULT NULL::text, p_modelo text DEFAULT NULL::text, p_tokens_in integer DEFAULT NULL::integer, p_tokens_out integer DEFAULT NULL::integer, p_latencia_ms integer DEFAULT NULL::integer, p_confidence numeric DEFAULT NULL::numeric, p_intent text DEFAULT NULL::text, p_motivo_handoff text DEFAULT NULL::text, p_contexto_usado jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb, p_mensagem_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT public._ia_pode_atuar() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  INSERT INTO public.ia_interacoes(
    lead_id, reserva_id, canal, direcao, autor, conteudo, resposta_final,
    modelo, tokens_in, tokens_out, latencia_ms, confidence, intent,
    motivo_handoff, contexto_usado, metadata, mensagem_id
  ) VALUES (
    p_lead_id, p_reserva_id, p_canal, p_direcao, 'ia', p_conteudo, p_resposta_final,
    p_modelo, p_tokens_in, p_tokens_out, p_latencia_ms, p_confidence, p_intent,
    p_motivo_handoff, COALESCE(p_contexto_usado,'{}'::jsonb), COALESCE(p_metadata,'{}'::jsonb), p_mensagem_id
  ) RETURNING id INTO v_id;
  PERFORM public._ia_log('ia_registrar_interacao',
    jsonb_build_object('modelo',p_modelo,'confidence',p_confidence,'intent',p_intent,'tokens_in',p_tokens_in,'tokens_out',p_tokens_out),
    jsonb_build_object('interacao_id',v_id), true, NULL, p_lead_id, p_reserva_id);
