CREATE OR REPLACE FUNCTION public.ia_solicitar_alteracao_reserva(p_reserva_id uuid, p_campo text, p_novo_valor text, p_motivo text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lead uuid; v_msg text; v_handoff uuid;
  v_whitelist text[] := ARRAY['observacoes_internas','motivacao_viagem','observacoes_importantes','tipo_grupo'];
  v_blacklist text[] := ARRAY[
    'valor_total','valor_pago','valor_entrada','saldo_restante',
    'status','status_financeiro','status_operacional','status_pagamento','status_documentacao',
    'data_id','expedicao_id','quantidade_participantes','protocolo'
  ];
  v_aplicado boolean := false;
BEGIN
  IF NOT public._ia_pode_atuar() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
  SELECT lead_id INTO v_lead FROM public.reservas WHERE id = p_reserva_id;
  IF v_lead IS NULL AND NOT FOUND THEN
    v_msg := 'Reserva não encontrada';
    PERFORM public._ia_log('ia_solicitar_alteracao_reserva',
      jsonb_build_object('campo',p_campo,'novo_valor',p_novo_valor),
      '{}'::jsonb, false, v_msg, NULL, p_reserva_id);
    RETURN jsonb_build_object('ok', false, 'motivo', v_msg);
  END IF;

  IF p_campo = ANY (v_blacklist) THEN
    v_msg := 'Campo proibido para a IA — exige humano';
    PERFORM public._ia_log('ia_solicitar_alteracao_reserva',
      jsonb_build_object('campo',p_campo,'novo_valor',p_novo_valor,'motivo',p_motivo),
      '{}'::jsonb, false, v_msg, v_lead, p_reserva_id);
    RETURN jsonb_build_object('ok', false, 'motivo', v_msg, 'bloqueado', true);
  END IF;

  IF p_campo = ANY (v_whitelist) THEN
    EXECUTE format('UPDATE public.reservas SET %I = $1, updated_at = now() WHERE id = $2', p_campo)
      USING p_novo_valor, p_reserva_id;
    v_aplicado := true;
    PERFORM public._ia_log('ia_solicitar_alteracao_reserva',
      jsonb_build_object('campo',p_campo,'novo_valor',p_novo_valor,'motivo',p_motivo,'aplicado',true),
      '{}'::jsonb, true, NULL, v_lead, p_reserva_id);
    RETURN jsonb_build_object('ok', true, 'aplicado', true);
  END IF;

  -- Campo fora da whitelist e fora da blacklist → handoff alta
  INSERT INTO public.ia_handoff_queue(motivo, prioridade, origem, lead_id, reserva_id, notas, status)
  VALUES (
    'Alteração de reserva solicitada pela IA: ' || p_campo,
    'alta', 'ia', v_lead, p_reserva_id,
    jsonb_build_object('campo',p_campo,'novo_valor',p_novo_valor,'motivo',p_motivo)::text,
    'pendente'
  ) RETURNING id INTO v_handoff;

  PERFORM public._ia_log('ia_solicitar_alteracao_reserva',
    jsonb_build_object('campo',p_campo,'novo_valor',p_novo_valor,'motivo',p_motivo,'handoff_id',v_handoff),
    jsonb_build_object('handoff_id',v_handoff), true, 'campo fora da whitelist — encaminhado para humano', v_lead, p_reserva_id);

  RETURN jsonb_build_object('ok', true, 'aplicado', false, 'handoff_id', v_handoff);
END $function$

CREATE OR REPLACE FUNCTION public.lead_etapa_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
    VALUES ('lead_criado','lead', NEW.id, jsonb_build_object('nome', NEW.nome, 'origem', NEW.origem, 'etapa', NEW.etapa_atendimento));
    INSERT INTO public.lead_conversas (lead_id, tipo_evento, conteudo, metadata)
    VALUES (NEW.id, 'lead_criado',
      'Lead criado' || COALESCE(' via ' || NEW.origem, ''),
      jsonb_build_object('origem', NEW.origem, 'canal_entrada', NEW.canal_entrada));
    RETURN NEW;
  END IF;

  IF NEW.etapa_atendimento IS DISTINCT FROM OLD.etapa_atendimento THEN
    INSERT INTO public.lead_conversas (lead_id, tipo_evento, conteudo, metadata)
    VALUES (NEW.id, 'alteracao_status',
      'Etapa alterada: ' || OLD.etapa_atendimento || ' → ' || NEW.etapa_atendimento,
      jsonb_build_object('de', OLD.etapa_atendimento, 'para', NEW.etapa_atendimento));

    IF NEW.etapa_atendimento = 'qualificado' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('lead_qualificado','lead', NEW.id, jsonb_build_object('nome', NEW.nome));
    ELSIF NEW.etapa_atendimento = 'proposta_enviada' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('lead_proposta_enviada','lead', NEW.id, jsonb_build_object('nome', NEW.nome));
    ELSIF NEW.etapa_atendimento = 'reserva_pendente' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('lead_reserva_pendente','lead', NEW.id, jsonb_build_object('nome', NEW.nome));
    ELSIF NEW.etapa_atendimento = 'participante_confirmado' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('lead_participante_confirmado','lead', NEW.id, jsonb_build_object('nome', NEW.nome));
    ELSIF NEW.etapa_atendimento = 'convertido' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('lead_convertido','lead', NEW.id, jsonb_build_object('nome', NEW.nome));
    ELSIF NEW.etapa_atendimento = 'concluido' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('lead_concluido','lead', NEW.id, jsonb_build_object('nome', NEW.nome));
    ELSIF NEW.etapa_atendimento = 'perdido' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('lead_perdido','lead', NEW.id, jsonb_build_object('nome', NEW.nome, 'motivo', NEW.motivo_perda));
    END IF;

    NEW.ultima_interacao_at := now();
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.temperatura_lead IS DISTINCT FROM OLD.temperatura_lead THEN
    INSERT INTO public.lead_conversas (lead_id, tipo_evento, conteudo, metadata)
    VALUES (NEW.id, 'alteracao_temperatura',
      'Temperatura: ' || OLD.temperatura_lead || ' → ' || NEW.temperatura_lead,
      jsonb_build_object('de', OLD.temperatura_lead, 'para', NEW.temperatura_lead));
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status_atendimento IS DISTINCT FROM OLD.status_atendimento THEN
    INSERT INTO public.lead_conversas (lead_id, tipo_evento, conteudo, metadata)
    VALUES (NEW.id, CASE WHEN NEW.status_atendimento = 'humano' THEN 'transferido_humano' ELSE 'alteracao_status' END,
      'Atendimento: ' || OLD.status_atendimento || ' → ' || NEW.status_atendimento,
      jsonb_build_object('de', OLD.status_atendimento, 'para', NEW.status_atendimento));

    IF NEW.status_atendimento = 'humano' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('lead_transferido_humano','lead', NEW.id, jsonb_build_object('nome', NEW.nome));
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

