CREATE OR REPLACE FUNCTION public.pagamento_registrado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_pago numeric;
  v_valor_total numeric;
  v_moeda_reserva text;
  v_status text;
  v_status_anterior text;
  v_status_op_anterior text;
  v_tem_divergente boolean;
  v_novo_status_op text;
BEGIN
  SELECT moeda, valor_total, status_financeiro, status_operacional
    INTO v_moeda_reserva, v_valor_total, v_status_anterior, v_status_op_anterior
  FROM public.reservas WHERE id = NEW.reserva_id;

  IF TG_OP = 'INSERT' AND (NEW.moeda IS NULL OR NEW.moeda = '') THEN
    NEW.moeda := COALESCE(v_moeda_reserva, 'BRL');
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao, valor, metadata)
    VALUES (NEW.reserva_id, 'pagamento',
      'Pagamento ' || NEW.tipo || ' (' || NEW.forma || '): ' || NEW.moeda || ' ' || NEW.valor::text,
      NEW.valor,
      jsonb_build_object('tipo', NEW.tipo, 'forma', NEW.forma, 'status', NEW.status, 'moeda', NEW.moeda));

    IF NEW.status = 'confirmado' AND NEW.tipo <> 'reembolso' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('pagamento_recebido','pagamento', NEW.id,
        jsonb_build_object('reserva_id', NEW.reserva_id, 'tipo', NEW.tipo, 'forma', NEW.forma, 'valor', NEW.valor, 'moeda', NEW.moeda));
    END IF;
  ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'confirmado' AND NEW.tipo <> 'reembolso' THEN
    INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
    VALUES ('pagamento_recebido','pagamento', NEW.id,
      jsonb_build_object('reserva_id', NEW.reserva_id, 'tipo', NEW.tipo, 'forma', NEW.forma, 'valor', NEW.valor, 'moeda', NEW.moeda));
  END IF;

  SELECT COALESCE(SUM(valor), 0) INTO v_total_pago
  FROM public.pagamentos
  WHERE reserva_id = NEW.reserva_id
    AND status = 'confirmado'
    AND tipo <> 'reembolso'
    AND moeda = COALESCE(v_moeda_reserva,'BRL');

  SELECT EXISTS (
    SELECT 1 FROM public.pagamentos
    WHERE reserva_id = NEW.reserva_id
      AND status = 'confirmado'
      AND tipo <> 'reembolso'
      AND moeda <> COALESCE(v_moeda_reserva,'BRL')
  ) INTO v_tem_divergente;

  v_status := CASE
    WHEN v_valor_total IS NULL OR v_valor_total = 0 THEN 'aguardando_pagamento'
    WHEN v_total_pago = 0 THEN 'aguardando_pagamento'
    WHEN v_total_pago >= v_valor_total THEN 'pago_integralmente'
    WHEN v_total_pago < v_valor_total THEN 'parcialmente_pago'
    ELSE 'aguardando_pagamento'
  END;

  -- Avança status_operacional: pre_reserva -> reserva_confirmada quando quitada
  v_novo_status_op := v_status_op_anterior;
  IF v_status = 'pago_integralmente'
     AND v_status_op_anterior IN ('pre_reserva','aguardando_pagamento') THEN
    v_novo_status_op := 'reserva_confirmada';
  END IF;

  UPDATE public.reservas
  SET valor_pago = v_total_pago,
      status_financeiro = v_status,
      status_operacional = v_novo_status_op,
      tem_pagamento_moeda_divergente = v_tem_divergente,
      updated_at = now()
  WHERE id = NEW.reserva_id;

  IF v_status = 'pago_integralmente' AND v_status_anterior IS DISTINCT FROM 'pago_integralmente' THEN
    UPDATE public.participantes
    SET status = 'confirmado', updated_at = now()
    WHERE reserva_id = NEW.reserva_id AND status <> 'confirmado';

    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao, metadata)
    VALUES (NEW.reserva_id, 'participantes_confirmados',
      'Reserva quitada — participantes marcados como confirmados',
      jsonb_build_object('total_pago', v_total_pago, 'moeda', v_moeda_reserva));
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.prevent_profile_role_self_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth_internal'
AS $function$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    IF NOT auth_internal.has_role(auth.uid(), 'admin'::app_role) THEN
      RAISE EXCEPTION 'Não é permitido alterar o campo role do próprio perfil.'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_cargo_developer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' AND OLD.chave = 'developer' THEN
    RAISE EXCEPTION 'O cargo Developer é protegido e não pode ser excluído.';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.chave = 'developer' THEN
    IF NEW.ativo = false THEN
      RAISE EXCEPTION 'O cargo Developer não pode ser desativado.';
    END IF;
    IF NEW.chave <> 'developer' THEN
      RAISE EXCEPTION 'A chave do cargo Developer não pode ser alterada.';
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_desenvolvedor_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (TG_OP = 'DELETE' AND OLD.role::text = 'desenvolvedor')
     OR (TG_OP = 'UPDATE' AND OLD.role::text = 'desenvolvedor' AND NEW.role::text <> 'desenvolvedor') THEN
    IF NOT public.has_role(auth.uid(), 'desenvolvedor'::app_role) THEN
      RAISE EXCEPTION 'Apenas um Desenvolvedor pode remover outro Desenvolvedor';
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.reconstruir_resumo_ia_reserva(reserva_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    r RECORD;
    p RECORD;
    parts_info TEXT := '';
    resumo TEXT;
BEGIN
    SELECT * INTO r FROM public.reservas WHERE id = reserva_id;
    IF NOT FOUND THEN RETURN NULL; END IF;

    -- Coleta info de participantes
    FOR p IN SELECT * FROM public.participantes WHERE reserva_id = r.id ORDER BY created_at ASC LOOP
        parts_info := parts_info || format(
            E'\n- %s: Peso %skg, Experiência: %s. Nascimento: %s.',
            p.nome, p.peso, p.experiencia_equestre, 
            CASE WHEN p.data_nascimento IS NOT NULL THEN to_char(p.data_nascimento, 'DD/MM/YYYY') ELSE 'Não informada' END
        );
        IF p.restricoes_alimentares IS NOT NULL AND p.restricoes_alimentares <> '' THEN
            parts_info := parts_info || ' Restrições: ' || p.restricoes_alimentares;
        END IF;
        IF p.observacoes_medicas IS NOT NULL AND p.observacoes_medicas <> '' THEN
            parts_info := parts_info || ' Obs Médicas: ' || p.observacoes_medicas;
        END IF;
    END LOOP;

    -- Constrói o resumo estruturado para a IA
    resumo := format(
        E'Resumo da Reserva %s (%s)\n' ||
        E'Cliente Responsável: %s\n' ||
        E'Expedição: %s (%s)\n' ||
        E'Tipo de Viagem: %s\n' ||
        E'Motivação: %s\n' ||
        E'Observações Importantes: %s\n' ||
        E'Valor Total: %s. Forma preferencial: %s\n' ||
        E'Participantes (%s):%s',
        r.protocolo, r.status_operacional,
        r.cliente_nome,
        r.expedicao_nome, r.data_label,
        COALESCE(r.tipo_grupo, 'Não informado'),
        COALESCE(r.motivacao_viagem, 'Não informada'),
        COALESCE(r.observacoes_importantes, 'Nenhuma'),
        to_char(r.valor_total, 'L"R$ "FM999G999G990D00'),
        COALESCE(r.forma_pagamento, 'Não informada'),
        r.quantidade_participantes,
        parts_info
    );

    RETURN resumo;
END;
$function$

CREATE OR REPLACE FUNCTION public.reserva_status_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao, metadata)
    VALUES (NEW.id, 'criacao', 'Reserva criada: ' || NEW.protocolo,
      jsonb_build_object('protocolo', NEW.protocolo, 'expedicao', NEW.expedicao_nome));
    INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
    VALUES ('reserva_criada', 'reserva', NEW.id,
      jsonb_build_object('protocolo', NEW.protocolo, 'expedicao_id', NEW.expedicao_id, 'valor_total', NEW.valor_total));
    RETURN NEW;
  END IF;

  IF NEW.status_financeiro IS DISTINCT FROM OLD.status_financeiro THEN
    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao, metadata)
    VALUES (NEW.id, 'status_financeiro',
      'Status financeiro: ' || OLD.status_financeiro || ' → ' || NEW.status_financeiro,
      jsonb_build_object('de', OLD.status_financeiro, 'para', NEW.status_financeiro));

    IF NEW.status_financeiro = 'pago_integralmente' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('pagamento_confirmado', 'reserva', NEW.id,
        jsonb_build_object('protocolo', NEW.protocolo, 'valor_pago', NEW.valor_pago));
    END IF;
  END IF;

  IF NEW.status_operacional IS DISTINCT FROM OLD.status_operacional THEN
    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao, metadata)
    VALUES (NEW.id, 'status_operacional',
      'Status operacional: ' || OLD.status_operacional || ' → ' || NEW.status_operacional,
      jsonb_build_object('de', OLD.status_operacional, 'para', NEW.status_operacional));

    IF NEW.status_operacional = 'reserva_confirmada' THEN
      INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
      VALUES ('reserva_confirmada', 'reserva', NEW.id,
        jsonb_build_object('protocolo', NEW.protocolo, 'expedicao_id', NEW.expedicao_id));
    END IF;
  END IF;

  IF NEW.contrato_enviado IS DISTINCT FROM OLD.contrato_enviado AND NEW.contrato_enviado THEN
    NEW.contrato_enviado_em := COALESCE(NEW.contrato_enviado_em, now());
    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao)
    VALUES (NEW.id, 'contrato', 'Contrato enviado ao cliente');
    INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
    VALUES ('contrato_enviado', 'reserva', NEW.id,
      jsonb_build_object('protocolo', NEW.protocolo));
  END IF;

  IF NEW.contrato_assinado IS DISTINCT FROM OLD.contrato_assinado AND NEW.contrato_assinado THEN
    NEW.contrato_assinado_em := COALESCE(NEW.contrato_assinado_em, now());
    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao)
    VALUES (NEW.id, 'contrato', 'Contrato assinado pelo cliente');
    INSERT INTO public.webhooks_eventos (evento, entidade, entidade_id, payload)
    VALUES ('contrato_assinado', 'reserva', NEW.id,
      jsonb_build_object('protocolo', NEW.protocolo));
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolver_lead_por_telefone(p_telefone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_norm text;
  v_suffix text;
  v_tipo text;
  v_lead_id uuid;
  v_reserva_id uuid;
  v_participante_id uuid;
  v_nome text;
  v_telefone text;
  v_etapa text;
  v_status_op text;
  v_expedicao text;
  v_data_exped text;
  v_moeda text;
  v_total int;
  v_ambiguo boolean := false;
BEGIN
  IF NOT public._ia_pode_atuar() THEN
    RAISE EXCEPTION 'Sem permissão para atuar como IA';
  END IF;

  v_norm := public._ia_normalizar_telefone(p_telefone);
  IF v_norm IS NULL OR length(v_norm) < 8 THEN
    PERFORM public._ia_log('resolver_lead_por_telefone',
      jsonb_build_object('telefone', p_telefone, 'normalizado', v_norm),
      jsonb_build_object('encontrado', false), false, 'Telefone inválido', NULL, NULL);
    RETURN jsonb_build_object('encontrado', false, 'motivo', 'telefone_invalido');
  END IF;

  -- Compara pelos últimos 8+ dígitos para tolerar DDI/DDD/zero a mais
  v_suffix := right(v_norm, 8);

  -- 1) LEADS
  SELECT count(*) INTO v_total
  FROM public.leads
  WHERE public._ia_normalizar_telefone(telefone) LIKE '%' || v_suffix;

  IF v_total > 0 THEN
    v_ambiguo := v_total > 1;
    SELECT l.id, l.nome, l.telefone, l.etapa_atendimento, l.expedicao_interesse
      INTO v_lead_id, v_nome, v_telefone, v_etapa, v_expedicao
    FROM public.leads l
    WHERE public._ia_normalizar_telefone(l.telefone) LIKE '%' || v_suffix
    ORDER BY COALESCE(l.ultima_interacao_at, l.updated_at, l.created_at) DESC
    LIMIT 1;
    v_tipo := 'lead';
  ELSE
    -- 2) RESERVAS
    SELECT count(*) INTO v_total
    FROM public.reservas
    WHERE public._ia_normalizar_telefone(cliente_telefone) LIKE '%' || v_suffix;

    IF v_total > 0 THEN
      v_ambiguo := v_total > 1;
      SELECT r.id, r.lead_id, r.cliente_nome, r.cliente_telefone,
             r.status_operacional, r.expedicao_nome, r.data_label, r.moeda
        INTO v_reserva_id, v_lead_id, v_nome, v_telefone,
             v_status_op, v_expedicao, v_data_exped, v_moeda
      FROM public.reservas r
      WHERE public._ia_normalizar_telefone(r.cliente_telefone) LIKE '%' || v_suffix
      ORDER BY COALESCE(r.updated_at, r.created_at) DESC
      LIMIT 1;
      v_tipo := 'reserva';
    ELSE
      -- 3) PARTICIPANTES
      SELECT count(*) INTO v_total
      FROM public.participantes
      WHERE public._ia_normalizar_telefone(telefone) LIKE '%' || v_suffix;

      IF v_total > 0 THEN
        v_ambiguo := v_total > 1;
        SELECT p.id, p.reserva_id, p.nome, p.telefone
          INTO v_participante_id, v_reserva_id, v_nome, v_telefone
        FROM public.participantes p
        WHERE public._ia_normalizar_telefone(p.telefone) LIKE '%' || v_suffix
        ORDER BY COALESCE(p.updated_at, p.created_at) DESC
        LIMIT 1;
        v_tipo := 'participante';

        IF v_reserva_id IS NOT NULL THEN
          SELECT r.lead_id, r.status_operacional, r.expedicao_nome, r.data_label, r.moeda
            INTO v_lead_id, v_status_op, v_expedicao, v_data_exped, v_moeda
          FROM public.reservas r WHERE r.id = v_reserva_id;
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_tipo IS NULL THEN
    PERFORM public._ia_log('resolver_lead_por_telefone',
      jsonb_build_object('telefone', p_telefone, 'normalizado', v_norm),
      jsonb_build_object('encontrado', false), true, 'nao_encontrado', NULL, NULL);
    RETURN jsonb_build_object('encontrado', false);
  END IF;

  PERFORM public._ia_log('resolver_lead_por_telefone',
    jsonb_build_object('telefone', p_telefone, 'normalizado', v_norm, 'ambiguo', v_ambiguo, 'total', v_total),
    jsonb_build_object('encontrado', true, 'tipo', v_tipo, 'lead_id', v_lead_id, 'reserva_id', v_reserva_id, 'participante_id', v_participante_id),
    true,
    CASE WHEN v_ambiguo THEN 'multiplos_resultados_retornou_mais_recente' ELSE NULL END,
    v_lead_id, v_reserva_id);

  RETURN jsonb_build_object(
    'encontrado', true,
    'tipo', v_tipo,
    'lead_id', v_lead_id,
    'reserva_id', v_reserva_id,
    'participante_id', v_participante_id,
    'nome', v_nome,
    'telefone', v_telefone,
    'etapa', v_etapa,
    'status_operacional', v_status_op,
    'expedicao', v_expedicao,
    'data_expedicao', v_data_exped,
    'moeda', v_moeda,
    'ambiguo', v_ambiguo,
    'total_matches', v_total
  );
END $function$

CREATE OR REPLACE FUNCTION public.sanitizar_origem_lead()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    origem_sanitizada TEXT;
BEGIN
    origem_sanitizada := NEW.origem;

    -- Se a origem for nula ou vazia, tenta usar utm_source
    IF origem_sanitizada IS NULL OR origem_sanitizada = '' THEN
        origem_sanitizada := NEW.utm_source;
    END IF;

    -- Lista de origens técnicas a serem ignoradas/substituídas
    IF origem_sanitizada ILIKE '%lovable.dev%' 
       OR origem_sanitizada ILIKE '%lovableproject.com%' 
       OR origem_sanitizada ILIKE '%localhost%' 
       OR origem_sanitizada ILIKE '%gptengineer.app%'
       OR origem_sanitizada IS NULL
    THEN
        -- Se for técnica, tenta classificar melhor ou deixa como 'Direto'
        IF NEW.utm_source IS NOT NULL AND NEW.utm_source != '' THEN
            origem_sanitizada := NEW.utm_source;
        ELSE
            origem_sanitizada := 'Direto';
        END IF;
    END IF;

    -- Padronização de nomes comuns
    IF origem_sanitizada ILIKE '%instagram%' THEN origem_sanitizada := 'Instagram';
    ELSIF origem_sanitizada ILIKE '%facebook%' THEN origem_sanitizada := 'Facebook';
    ELSIF origem_sanitizada ILIKE '%google%' AND (NEW.utm_medium = 'cpc' OR NEW.utm_medium = 'ads') THEN origem_sanitizada := 'Google Ads';
    ELSIF origem_sanitizada ILIKE '%google%' THEN origem_sanitizada := 'Google Orgânico';
    ELSIF origem_sanitizada ILIKE '%whatsapp%' THEN origem_sanitizada := 'WhatsApp';
    END IF;

    NEW.origem := origem_sanitizada;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.slugify_unique_expedicao(base text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  candidato text;
  base_clean text;
  i int := 1;
BEGIN
  base_clean := lower(regexp_replace(unaccent(coalesce(base, 'expedicao')), '[^a-zA-Z0-9]+', '-', 'g'));
  base_clean := regexp_replace(base_clean, '(^-+|-+$)', '', 'g');
  IF base_clean = '' THEN base_clean := 'expedicao'; END IF;
  candidato := base_clean;
  WHILE EXISTS (SELECT 1 FROM public.expedicoes WHERE slug = candidato) LOOP
    i := i + 1;
    candidato := base_clean || '-' || i::text;
  END LOOP;
  RETURN candidato;
END;
$function$

CREATE OR REPLACE FUNCTION public.tr_handoff_atualizar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.atualizado_em := now();
  IF TG_OP = 'UPDATE' THEN
    IF NEW.atribuido_para IS DISTINCT FROM OLD.atribuido_para THEN
      NEW.responsavel_anterior := OLD.atribuido_para;
      NEW.responsavel_atual := NEW.atribuido_para;
    END IF;
    IF NEW.status = 'resolvido' AND OLD.status <> 'resolvido' THEN
      NEW.resolvido_em := COALESCE(NEW.resolvido_em, now());
    END IF;
  ELSIF TG_OP = 'INSERT' THEN
    NEW.responsavel_atual := COALESCE(NEW.responsavel_atual, NEW.atribuido_para);
    -- SLA padrão por prioridade (em horas) se não informado
    IF NEW.prazo IS NULL THEN
      NEW.prazo := now() + CASE NEW.prioridade
        WHEN 'critica' THEN INTERVAL '2 hours'
        WHEN 'alta'    THEN INTERVAL '8 hours'
        WHEN 'media'   THEN INTERVAL '24 hours'
        ELSE                INTERVAL '72 hours'
      END;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tr_herdar_moeda_data()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_moeda text;
BEGIN
  IF NEW.expedicao_id IS NOT NULL THEN
    SELECT moeda INTO v_moeda FROM public.expedicoes WHERE id = NEW.expedicao_id;
    IF v_moeda IS NOT NULL AND v_moeda <> '' THEN
      NEW.moeda := v_moeda;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tr_herdar_moeda_pagamento()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_moeda text;
BEGIN
  IF NEW.moeda IS NULL OR NEW.moeda = '' THEN
    SELECT moeda INTO v_moeda FROM public.reservas WHERE id = NEW.reserva_id;
    NEW.moeda := COALESCE(NULLIF(v_moeda,''), 'BRL');
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tr_herdar_moeda_reserva()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_moeda text;
BEGIN
  IF NEW.data_id IS NOT NULL THEN
    SELECT moeda INTO v_moeda FROM public.datas WHERE id = NEW.data_id;
  END IF;
  IF (v_moeda IS NULL OR v_moeda = '') AND NEW.expedicao_id IS NOT NULL THEN
    SELECT moeda INTO v_moeda FROM public.expedicoes WHERE id = NEW.expedicao_id;
  END IF;
  IF v_moeda IS NOT NULL AND v_moeda <> '' THEN
    NEW.moeda := v_moeda;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tr_ia_kb_atualizacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at := now();
  IF TG_OP = 'UPDATE' THEN
    IF auth.uid() IS NOT NULL THEN NEW.updated_by := auth.uid(); END IF;
    IF NEW.conteudo IS DISTINCT FROM OLD.conteudo OR NEW.titulo IS DISTINCT FROM OLD.titulo THEN
      NEW.embedding_pendente := true;
    END IF;
  ELSIF TG_OP = 'INSERT' THEN
    IF auth.uid() IS NOT NULL THEN
      NEW.created_by := COALESCE(NEW.created_by, auth.uid());
      NEW.updated_by := COALESCE(NEW.updated_by, auth.uid());
    END IF;
    NEW.versao := COALESCE(NEW.versao, 1);
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tr_participante_tarefa_auto()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_lead uuid; v_falta text := '';
BEGIN
  IF NEW.peso IS NULL THEN v_falta := v_falta || 'peso'; END IF;
  IF NEW.experiencia_equestre IS NULL OR NEW.experiencia_equestre = '' THEN
    v_falta := v_falta || CASE WHEN v_falta = '' THEN '' ELSE ' e ' END || 'experiência equestre';
  END IF;
  IF v_falta = '' THEN RETURN NEW; END IF;
  SELECT lead_id INTO v_lead FROM public.reservas WHERE id = NEW.reserva_id;
  PERFORM public.criar_tarefa_idempotente(
    'Completar ficha do participante ' || COALESCE(NEW.nome,'(sem nome)') || ' — falta ' || v_falta,
    'operacional','automacao','media',
    v_lead, NEW.reserva_id, NEW.id, INTERVAL '48 hours');
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_log_reserva_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (OLD.status IS DISTINCT FROM NEW.status) THEN
    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao, metadata)
    VALUES (NEW.id, 'status', 'Status alterado de ' || OLD.status || ' para ' || NEW.status, jsonb_build_object('de', OLD.status, 'para', NEW.status));
  END IF;

  IF (OLD.valor_total IS DISTINCT FROM NEW.valor_total) THEN
    INSERT INTO public.reserva_historico (reserva_id, tipo, descricao, metadata)
    VALUES (NEW.id, 'financeiro', 'Valor total alterado de ' || OLD.valor_total || ' para ' || NEW.valor_total, jsonb_build_object('de', OLD.valor_total, 'para', NEW.valor_total));
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_recalcular_vagas()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.recalcular_vagas_data(COALESCE(NEW.data_id, OLD.data_id));
  IF TG_OP = 'UPDATE' AND NEW.data_id IS DISTINCT FROM OLD.data_id THEN
    PERFORM public.recalcular_vagas_data(OLD.data_id);
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.trg_validar_participante_idade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (NEW.data_nascimento > (CURRENT_DATE - INTERVAL '8 years')) THEN
    RAISE EXCEPTION 'Idade mínima permitida é 8 anos.';
  END IF;
  RETURN NEW;
END;
$function$

